void my_put_nbr(int n)
{
    int divisor = 1;
    unsigned int num;

    if (n < 0) {
        num = -n;
        my_putchar('-');
    } else {
        num = n;
    }
    while (num / divisor >= 10) {
        divisor *= 10;
    }
    while (divisor > 0) {
        my_putchar((num / divisor) + '0');
        num %= divisor;
        divisor /= 10;
    }
}

