void place_next_queen(board_t *b, int bound)
{
    int middle = b->size;
    int next_placement;

    if (!b->colj)
        middle >>= 1;
    for (int i = 0; i < bound; i++) {
        if (!square_is_free(b, i))
            continue;
        set_queen(b, i);
        if (b->colj == b->size)
            b->solutions++;
        next_placement = (b->queens[0] != middle) ? b->size : middle;
        place_next_queen(b, next_placement);
        remove_queen(b, i);
    }
}

int count_valid_queens_placements(int n)
{
    int diag_size = 2 * n - 1;
    int size = 2 * (n + diag_size);
    int mem[size + 2 * n + diag_size];
    board_t board = {
        .size = n,
        .queens = mem,
        0
    };

    board.column = board.queens + n;
    board.diag_up = board.column + n;
    board.diag_down = board.diag_up + diag_size;
    for (int i = 0; i < n; i++)
        board.queens[i] = EMPTY;
    for (int i = n; i < size; i++)
        board.queens[i] = QUEEN;
    place_next_queen(&board, (n >> 1) + (n & 1));
    return (n == 1) ? 1 : board.solutions << 1;
}

