int is_unique(int n)
{
    int tdigit;
    int digit;
    int tmp;

    while (n) {
        digit = n % 10;
        n /= 10;
        tdigit = n % 10;
        tmp = n;
        if (tdigit > digit) {
            return 0;
        }
        while (tmp && digit != tmp % 10) {
            tmp /= 10;
        }
        if (tmp != 0) {
            return 0;
        }
    }
    return 1;
}

