int test_diago(int array[100][100], int i, int j, int n)
{
    int p = 0;

    while (j - p >= 0 && i + p < n) {
        if (array[j - p][i + p] == 1)
            return (0);
        p++;
    }
    p = 0;
    while (j + p < n && i - p >= 0) {
        if (array[j + p][i - p] == 1)
            return (0);
        p++;
    }
    p = 0;
    while (i - p >= 0 && j - p >= 0) {
        if (array[i - p][j - p] == 1)
            return (0);
        p++;
    }
    return (1);
}

int test_alignement(int array[100][100], int i, int j, int n)
{
    int p = 0;

    while (p < n) {
        if (array[p][j] == 1)
            return (0);
        p++;
    }
    p = 0;
    while (p < n) {
        if (array[i][p] == 1)
            return (0);
        p++;
    }
    return (test_diago(array, i, j, n));
}

