int verif(int chess[], int l, int col, int n)
{
    int i;
    int j;

    for (i = 0; i < col; i++) {
        if (chess[l * n + i] == 1)
            return 0;
    }
    j = col;
    for (i = l; i >= 0 && j >= 0; i--) {
        if (chess[i * n + j] == 1)
            return 0;
        j--;
    }
    j = col;
    for (i = l; j >= 0 && i < n; i++) {
        if (chess[i * n + j] == 1)
            return 0;
        j--;
    }
    return 1;
}

int demarche(int chess[], int col, int n, int *cpt)
{
    int res = 0;
    int i;

    if (col >= n) {
        (*cpt)++;
        return 1;
    }
    for (i = 0; i < n; i++) {
        if (verif(chess, i, col, n)) {
            chess[i * n + col] = 1;
            res += demarche(chess, col + 1, n, cpt);
            chess[i * n + col] = 0;
        }
    }
    return res;
}

int count_valid_queens_placements(int n)
{
    int chess[n][n];
