void init_tab(int n, char array[n][n])
{
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= n; ++j) {
            array[i][j] = '*';
        }
    }
}

int get_col(int n, char board[n][n], int line)
{
    for (int i = 0; i < n; ++i) {
        if (board[line][i] == 'Q') {
            board[line][i] = '*';
            return i;
        }
    }
    return -1;
}

int check_diagonale(int n, char array[n][n], int init_row, int init_col)
{
    int diag_i = init_row;
    int diag_j = init_col;

    while (diag_i >= 0 && diag_j >= 0) {
        if (array[diag_i][diag_j] == 'Q')
            return 1;
        diag_i -= 1;
        diag_j -= 1;
    }
    diag_i = init_row;
    diag_j = init_col;
    while (diag_i >= 0 && diag_j < n) {
        if (array[diag_i][diag_j] == 'Q')
            return 1;
        diag_i -= 1;
        diag_j += 1;
    }
    return 0;
}

