int place_queen(int n, char board[n][n], int row, int col)
{
    for (int i = col; i < n; i++) {
        if (is_valid(n, board, row, i) == 0) {
            board[row][i] = 'Q';
            return 1;
        }
    }
    return 0;
}

int queen(int n, char board[n][n], int row, int col)
{
    static int count = 0;

    if (row < 0)
        return count;
    if (row == n) {
        count = count + 1;
        get_col(n, board, row);
        queen(n, board, row - 1, get_col(n, board, row - 1) + 1);
    }
    if (row < n) {
        if (place_queen(n, board, row, col) == 1) {
            queen(n, board, row + 1, 0);
        } else {
            queen(n, board, row - 1, get_col(n, board, row - 1) + 1);
        }
    }
    return count;
}

