struct CombParams {
    int depth;
    int total;
    int *count;
};

int count_dig(int number)
{
    int count = 0;

    if (number == 0) {
        return 1;
    }
    while (number != 0) {
        number /= 10;
        count++;
    }
    return count;
}

int put_chars(int number, int n)
{
    int current_digits = count_dig(number);

    for (int i = 0; i < (n - current_digits); i++) {
        my_putchar('0');
    }
    my_put_nbr(number);
    return 0;
}

void create_combs(int n, int start, int current, struct CombParams *params)
{
    if (params->depth == n) {
        put_chars(current, n);
        (*(params->count))++;
        if (*(params->count) < params->total) {
            my_putchar(44);
            my_putchar(32);
        }
        return;
    }
    for (int i = start; i <= 9; i++) {
        params->depth++;
        create_combs(n, i + 1, current * 10 + i, params);
        params->depth--;
    }
}

void my_print_combn(int n)
{
    int total_combinations = 1;
    int count = 0;
    struct CombParams params = {0, 0, &count};

    for (int i = 0; i < n; i++) {
        total_combinations *= (10 - i);
        total_combinations /= (i + 1);
    }
