bool is_dangerous(int x1, int y1, int x2, int y2)
{
    int maxX = x1 > x2 ? x1 : x2;
    int minX = x1 > x2 ? x2 : x1;
    int maxY = y1 > y2 ? y1 : y2;
    int minY = y1 > y2 ? y2 : y1;

    if (x1 == x2 || y1 == y2)
        return true;
    return (maxX - minX) == (maxY - minY);
}

