    }
    return 1;
}

int special_cases(int nb, int *neg, int *overflow)
{
    if (nb == -2147483648) {
        nb = 2147483647;
        *neg = 1;
        *overflow = 1;
        return nb;
    }
    if (nb < 0) {
        nb = - nb;
        *neg = 1;
        return nb;
    }
    if (nb == 0) {
        my_putchar('0');
        return 0;
    }
    return nb;
}

char *final_str(char *chaine, int *index, int *neg, int *overflow)
{
    for (int i = *index; i >= 0; i --) {
        if (*neg == 1) {
            my_putchar('-');
            *neg = 0;
        }
        if (*overflow == 1 && i == 0) {
            my_putchar('8');
            *overflow = 0;
        } else
        my_putchar(chaine[i]);
    }
}

int my_put_nbr(int nb)
{
    char chaine[11] = {0};
    int index = 0;
    int neg = 0;
    int overflow = 0;

    nb = (special_cases(nb, &neg, &overflow));
    while (nb % 10 >= 1) {
        chaine[index] = (nb % 10) + '0';
        nb = nb / 10;
        index++;
    }
    final_str(chaine, &index, &neg, &overflow);
}

