int compare(char *str, char const *comp, int count, int n)
{
    char ptc = comp[n];
    char ptr = str[count];

    if (ptr == ptc && ptr != '\0' && ptc != '\0') {
        return compare(str, comp, count + 1, n + 1);
    }else if (comp[n] == '\0') {
        return 1;
    }else {
        return 0;
    }
}

char *my_strstr(char *str, char const *to_find)
{
    int lns = len_str(str);
    int lnt = len_str(to_find);

    if (lnt == 0) {
        return str;
    }
    for (int i = 0; i < lns && lns - i >= lnt; i++) {
        if (compare(str, to_find, i, 0) == 1) {
            return &str[i];
        }
    }
    return NULL;
}

