int check_larger(char const *s1, char const *s2, int count, int v)
{
    if (s1[count] == '\n') {
        return 1;
    }else if (s2[count] == '\n') {
        return -1;
    }else {
        return v;
    }
}

int compare_strings(char const *s1, char const *s2, int count)
{
    if (s1[count] == s2[count]) {
        return compare_strings(s1, s2, count + 1);
    }else if (s1[count] == '\0' && s2[count] == '\0') {
        return 0;
    }else {
        if (s1[count] > s2[count]) {
            return check_larger(s1, s2, count, 1);
        }else {
            return check_larger(s1, s2, count, -1;
        }
    }
}

int my_strcmp(char const *s1, char const *s2)
{
