char *my_strstr(char *str, char const *to_find)
{
    int targetlock = -1;
    int len = my_strlen(str) - 1;

    for (int i = 0; i < len; i += 1){
        if (str[i] == to_find[i] ||
            (hunter(*str, *to_find, targetlock) == 1)){
            targetlock = i;
            return (str[targetlock]);
        }
    }
    return (0);
}

int hunter(char *str, char const *to_find, int targetlock)
{
    int len = my_strlen(str) - 1;
    int lenght = my_strlen(to_find) - 1;
    int countdown = lenght - 1;

    if ((len - targetlock) > lenght){
        return (0);
    }
    for (int i = 0; i < lenght - 2; i += 1){
        if (str[targetlock + i] == to_find[targetlock + i]){
            countdown -= 1;
            }
        }
    if (countdown == 0){
        return (1);
    }
    return (0);
}

