char *my_revstr(char *str)
{
    int i = 0;
    int swap;
    int len = slen(str) - 1;

    while (i <= len / 2){
        swap = str[i];
        str[i] = str[len - i];
        str[len - i] = swap;
        i++;
    }
    return str;
}

