        m += 1;
    }
    m -= 1;
    boucle(m, p, str);
    return (str);
}

void boucle(int m, int p, char *str)
{
    int diff = m - p;
    int temp1;
    int temp2;

    while (diff >= 1) {
        temp1 = str[m];
        temp2 = str[p];
        str[m] = temp2;
        str[p] = temp1;
        m -= 1;
        p += 1;
        diff = m - p;
    }
}

