int is_plus_min(char const *str, int i, char const *base, int min)
{
    int res = 0;
    int len_base = lenght(base);

    while (str[i] && is_in_base(str[i], base) > -1){
        res = res * len_base + is_in_base(str[i], base);
        i++;
        res *= min;
        if (res < -2147483648 || res > 2147483647)
            return (0);
        res *= min;
    }
    return res;
}

