    while (is_in_base(str[i], base) == -1
        && !(str[i] == '+') && !(str[i] == '-') && str[i]) {
        i++;
    }
    while (str[i] == '-' || str[i] == '+'){
        if (str[i] == '-')
            min *= -1;
        i++;
    }
