int check_letter(char *str, int i)
{
    if (is_alpha(str[i], 'a', 'z') && i == 0) {
        str[i] -= 32;
        return 1;
    }
    if (is_alpha(str[i], 'a', 'z') && !is_num(str[i - 1])
        && !is_alpha(str[i - 1], 'a', 'z') &&
        !is_alpha(str[i - 1], 'A', 'Z')) {
