        ++cur;
    }
    return cur;
}

static int is_number(char const c)
{
    if ((c <= '9' && c >= '0') || (c >= 'A' && c <= 'Z')) {
        return 1;
    }
    return 0;
}

static int find_first_number(char const *str, int len)
{
    for (int i = 0; i < len - 1; ++i) {
        if (is_number(str[i])) {
            return i;
        }
    }
    return -1;
}

static void reverse_if_needed(long *num, int sign)
{
    if (sign) {
        *num *= -1;
    }
}

static int find_last_number(char const *str, int first_num, int len)
{
    for (int i = first_num; i < len; i++) {
        if (!is_number(str[i])) {
            return i + first_num;
        }
    }
    return len;
}

static int convert_to_num(char c)
{
    if (c >= '0' && c <= '9')
        return c - 48;
    if (c >= 'A' && c <= 'Z')
        return c - 55;
    return 0;
}

int my_getnbr(char const *str)
{
    int len = my_strlen(str);
    int num_start = find_first_number(str, len);
    int num_end = find_last_number(str, num_start, len);
    int sign = 0;
    long result = 0;
    long grade10 = 1;

    if (num_start < 0)
        return 0;
    sign = determine_sign(str, num_start);
    for (int i = num_end - 1; i >= num_start; --i) {
        result += grade10 * (str[i] - 48);
        if (result > LIMIT + sign)
            return 0;
        grade10 *= 10;
    }
    reverse_if_needed(&result, sign);
    return (int)result;
}

int my_getnbr_base(char const *str, char const *base)
{
    int len = my_strlen(str);
    int num_start = find_first_number(str, len);
    int num_end = find_last_number(str, num_start, len);
    int sign = 0;
    long result = 0;
    long grade10 = 1;
    int base_num = my_getnbr(base);

    if (num_start < 0)
        return 0;
    sign = determine_sign(str, num_start);
    for (int i = num_end - 1; i >= num_start; --i) {
        result += grade10 * (convert_to_num(str[i]));
        if (result > LIMIT + sign)
            return 0;
        grade10 *= base_num;
    }
    reverse_if_needed(&result, sign);
    return (int)result;
}

