int find_char(char const c, char const *base)
{
    for (int i = 0; base[i] != '\0'; ++i) {
        if (base[i] == c) {
            return i;
        }
    }
    return -1;
}

int get_count(char const *str, char const *base, int i)
{
    static int nb = 0;

    if (str[i] != '\0') {
        get_count(str, base, i + 1);
        nb = nb + find_char(str[i], base)
        * (my_pow(my_strlen(base), my_strlen(str) - i - 1));
    }
    return nb;
}

int my_getnbr_base(char const *str, char const *base)
{
    int sign = 0;
    int neg = 1;

    while (str[0] == '-' || str[0] == '+') {
        if (str[0] == '-')
            sign += 1;
        str++;
    }
    for (int i = 0; str[i] != '\0'; ++i) {
        if (find_char(str[i], base) == -1) {
            return 0;
        }
    }
    if (sign % 2 == 1)
        neg *= -1;
    return neg * get_count(str, base, 0);
}

