char	*my_strcapitalize(char *str)
{
    int i = 1;

    if (str[0] >= 'a' && str[0] <= 'z')
            str[0] -= 32;
    while (str[i]) {
        if (verif_space(str, i) && verif_lowercase(str, i))
            str[i] -= 32;
        if (!verif_space(str, i) && verif_uppercase(str, i))
            str[i] += 32;
        i++;
    }
    return (str);
