    char temp_str = str[0];

    for (int i = 0; str[i] != '\0'; i++)
        len++;
    for (int i = 0; i <= len / 2; i++) {
        temp_str = str[i];
        str[i] = str[(len - 1) - i];
        str[(len - 1) - i] = temp_str;
    }
    return str;
}

