            return (0);
        }
    }
    return (1);
}

int my_strlen(char const *str)
{
    int len = 0;

    for (int i = 0; str[i] != '\0'; i += 1) {
        len += 1;
    }
    return (len);
}

int my_str_islower(char const *str)
{
    for (int i = 0; str[i] != '\0'; i += 1) {
        if (!(str[i] >= 'a' && str[i] <= 'z')) {
            return (0);
        }
    }
    return (1);
}

int my_str_isnum(char const *str)
{
    for (int i = 0; str[i] != '\0'; i += 1) {
        if (!is_num(str[i])) {
            return (0);
        }
    }
    return (1);
}

char *my_strupcase(char *str)
{
    for (int i = 0; str[i] != '\0'; i += 1) {
        if (str[i] >= 97 && str[i] <= 122) {
            str[i] = str[i] - 32;
        }
        continue;
    }
    return (str);
}

int my_strcmp(char const *s1, char const *s2)
{
    int max_len;

    if (my_strlen(s1) > my_strlen(s2)) {
        max_len = my_strlen(s1);
    } else {
        max_len = my_strlen(s2);
    }
    for (int i = 0; i < max_len; i += 1) {
        if (s1[i] == s2[i]) {
            continue;
        }
        return (s1[i] - s2[i]);
    }
    return (0);
}

int my_str_isalpha(char const *str)
{
    for (int i = 0; str[i] != '\0'; i += 1) {
        if (!is_alpha(str[i])) {
            return (0);
        }
    }
    return (1);
}

int my_str_isupper(char const *str)
{
    for (int i = 0; str[i] != '\0'; i += 1) {
        if (!(str[i] >= 'A' && str[i] <= 'Z')) {
            return (0);
        }
    }
    return (1);
}

char *my_strcpy(char *dest, char const *src)
{
    int len = my_strlen(src);

    for (int i = 0; src[i] != '\0'; i += 1) {
        dest[i] = src[i];
    }
    dest[len] = '\0';
    return dest;
}

int is_num(char str)
{
    return (str >= '0' && str <= '9');
}

int is_low(char str)
{
    return (str >= 'a' && str <= 'z');
}

int is_up(char str)
{
    return (str >= 'A' && str <= 'Z');
}

int is_alpha(char *str)
{
    return (is_low(str) || is_up(str));
}

char *my_strcapitalize(char *str)
{
    int is_start = 1;

    for (int i = 0; str[i] != '\0'; i += 1) {
        if (!is_alpha(str[i]) && !is_num(str[i])) {
            is_start = 1;
            continue;
        }
        if (is_low(str[i]) && is_start) {
            str[i] = str[i] - 32;
        }
        if (is_up(str[i]) && !is_start) {
            str[i] = str[i] + 32;
        }
        is_start = 0;
    }
    return str;
}

char *my_revstr(char *str)
{
    int len = my_strlen(str);
    char temp;

    for (int i = 0; i < (len / 2); i += 1) {
        temp = str[i];
        str[i] = str[len - 1 - i];
        str[len - 1 - i] = temp;
    }
    return str;
}

