int my_put_nbr_base(int nbr, char const *base)
{
    int len_base = my_strlen(base);
    int r = 0;

    if (nbr < 0) {
        nbr *= -1;
        r += my_putchar('-');
        r += my_put_nbr_base(nbr, base);
    } else if (nbr >= len_base) {
        r += my_put_nbr_base(nbr / len_base, base);
        r += my_putchar(base[nbr % len_base]);
    } else
        r += my_putchar(base[nbr]);
    return r;
}

