int getneg(const char *str, int *nlen, int *startoff, const char *base)
{
    int i = 0;
    int neg = 1;

    while (str[i] == '+' || str[i] == '-') {
        if (str[i] == '-')
            neg = -neg;
        i++;
    }
    *startoff = i;
    while (strget(str[i], base) != -1) {
        i++;
    }
    *nlen = i - *startoff;
    return neg;
}

