char *my_strcapitalize(char *str)
{
    int i = 0;
    int inword = 0;

    while (str[i] != '\0') {
        if (is_wordpart(str[i]) && inword > 0) {
            str[i] = setlower(str[i]);
            inword++;
        }
        if (is_wordpart(str[i]) && inword == 0) {
            str[i] = setcapital(str[i]);
            inword++;
        }
        if (!is_wordpart(str[i])) {
            inword = 0;
        }
        i++;
    }
    return str;
}

