int is_letter(char letter)
{
    if ((letter >= 'a' && letter <= 'z') || (letter >= 'A' && letter <= 'Z')) {
        return 1;
    }
    if (letter >= '0' && letter <= '9') {
        return 1;
    }
    return 0;
}

char *my_strcapitalize(char *str)
{
    my_strlowcase(str);
    for (int i = 0 ; str[i] != '\0' ; i++) {
        if (is_letter(str[i]) != 1)
            continue;
        if (is_letter(str[i - 1]) == 0) {
            str[i] -= 32;
        }
    }
    return str;
}

