int my_compute_power_rec(int nb, int p)
{
    int x = 0;
    int y = 0;

    if (p == 0)
        return 1;
    if (p < 0)
        return 0;
    else {
        x = my_compute_power_rec(nb, p - 1);
        y = x * nb;
        if (y != 0 && y / nb != x)
            return 0;
        return y;
    }
}

