void capitalize_word(char *str, int *i, int *new_word)
{
    if (*new_word) {
        if (str[*i] >= 'a' && str[*i] <= 'z')
            str[*i] = str[*i] - ('a' - 'A');
        *new_word = 0;
    } else {
        if (str[*i] >= 'A' && str[*i] <= 'Z')
            str[*i] = str[*i] + ('a' - 'A');
    }
}

