static int is_lower(char c)
{
    return c >= 97 && c <= 122;
}

static int is_upper(char c)
{
    return c >= 65 && c <= 90;
}

static int is_letter(char c)
{
    return is_lower(c) || is_upper(c) || (c >= 48 && c <= 57);
}

char *my_strcapitalize(char *str)
{
    char c;
    int my_word = 0;
    char *ptr = str;

    do {
        c = *str;
        if (is_letter(c))
            my_word++;
        else
            my_word = 0;
        if (my_word == 1 && is_lower(c))
            *str = c - 32;
        else if (my_word > 1 && is_upper(c))
            *str = c + 32;
    } while (*str++ != '\0');
    return ptr;
}

