        if (i == 0 && (str[i] >= 'a' && str[i] <= 'z'))
            str[i] -= 32;
        if ((str[i] >= 'a' && str[i] <= 'z') && i > 0)
            str = turn_upcase(str, i);
        if ((str[i] >= 'A' && str[i] <= 'Z') && i > 0)
            str = turn_lowcase(str, i);
    }
    return (str);
