    int firstChar = 0;
    int lastChar = (my_revstrlen(str) - 1);

    while (firstChar < lastChar) {
        tempo = str[firstChar];
        str[firstChar] = str[lastChar];
        str[lastChar] = tempo;
        firstChar++;
        lastChar--;
    }
    return (str);
}

