void swap_chars(int s, int f, char *str)
{
    int t = f % 2;
    char a;

    while (s != f) {
        if ((t > 0 && s - f == 1)) {
            return;
        }
        a = str[s];
        str[s] = str[f];
        str[f] = a;
        s++;
        f--;
    }
}

char *my_revstr(char *str)
{
    int s = 0;
    int f = 0;

    if (str[0] == '\0') {
        return (str);
    }
    for (int i = 0; str[i] != '\0'; i++) {
        f++;
    }
    f--;
    swap_chars(s, f, str);
    return (str);
}

