void nbr_to_hex(int nbr)
{
    char hex[50];
    int i = 0;
    int temp;

    while (nbr != 0) {
        temp = nbr % 16;
        if (temp < 10) {
            hex[i++] = temp + '0';
        } else {
            hex[i++] = temp - 10 + 'A';
        }
        nbr /= 16;
    }
    for (int j = i - 1; j >= 0; j--) {
        my_putchar(hex[j]);
    }
    my_putchar('\n');
}

void nbr_to_bin(int nbr)
{
    char bin[50];
    int i = 0;
    int temp;

    while (nbr != 0) {
        temp = nbr % 2;
        bin[i++] = temp + '0';
        nbr /= 2;
    }
    for (int j = i - 1; j >= 0; j--) {
        my_putchar(bin[j]);
    }
    my_putchar('\n');
}

int my_putnbr_base(int nbr, char const *base)
{
    if (base == "bin") {
        nbr_to_bin(nbr);
    }
    if (base == "hexadecimal") {
        nbr_to_hex(nbr);
    }
}

