void conditions(char *str, int i)
{
    if (str[i + 1] >= 'a' && str[i + 1] <= 'z'){
        if (str[i] >= ' ' && str[i] <= '/' || str[i] >= ':' && str[i] <= '@')
            str[i + 1] -= 32;
    }
    if (str[i] >= 'A' && str[i] <= 'Z'){
        if (str[i + 1] >= 'A' && str[i + 1] <= 'Z')
            str[i + 1] += 32;
        if (str[i - 1] >= 'a' && str[i - 1] <= 'z')
            str[i] += 32;
    }
    if (str[i] >= '0' && str[i] <= '9'){
        if (str[i + 1] >= 'A' && str[i + 1] <= 'Z')
            str[i + 1] += 32;
    }
}

