static void print_hex(char chr)
{
    unsigned char c;
    unsigned char temp;

    write(1, "\\", 1);
    c = chr;
    if (chr < 0){
        c = -chr;
        write(1, "-", 1);
    }
    temp = c / 16 + '0';
    if (temp > '9')
        temp += 39;
    write(1, &temp, 1);
    temp = c % 16 + '0';
    if (temp > '9')
        temp += 39;
    write(1, &temp, 1);
}

