int my_getnbr_base(char const *str, char const *base)
{
    int i = 0;
    int minus = 0;
    int nb = 0;
    int len_base = mystrlen(base);

    if (len_base == 0)
        return 0;
    while (str[i] == '-' || str[i] == '+' || my_isbase(str[i], base)) {
        if (my_isbase(str[i], base))
            nb = nb * len_base + str[i] - place(base, str[i]);
        if (str[i] == '-')
            minus = minus + 1;
        if (my_isbase(str[i], base) == 1 && my_isbase(str[i + 1], base) == 0)
            break;
        i = i + 1;
    }
    if (minus % 2 == 1)
        nb = -nb;
    return nb;
}

