char *get_str_nbr_hexa(int ptr)
{
    int power = 16;
    int tmp = 0;
    char res[9] = {0};
    char base[] = "0123456789abcdef";

    while (ptr / power > 16 - 1)
        power = power * 16;
    for (int i = 7; i != -1; i--) {
        if (power < 1)
            power = 1;
        tmp = ptr / power;
        res[i] = base[tmp];
        ptr = ptr % power;
        power = power / 16;
    }
    return res;
}

void create_pt(char const *str)
{
    int ptr = str;
    char *repres = get_str_nbr_hexa(ptr);

    if (mystrlen(repres) < 8) {
