void uppercase(char *c)
{
    if (*c >= 'a' && *c <= 'z') {
        *c -= 'a' - 'A';
    }
}

void lowercase(char *c)
{
    if (*c >= 'A' && *c <= 'Z')
        *c += 'a' - 'A';
}

char *my_strcapitalize(char *str)
{
    int i = 1;

    uppercase(str);
    while (str[i] != '\0') {
        if (is_letter(str[i]) && !is_letter(str[i - 1]))
            uppercase(str + i);
        else
            lowercase(str + i);
        i++;
    }
    return str;
}

int is_letter_upper(char c)
{
