char swap_char(char *a, char *b)
{
    char c = *a;

    *a = *b;
    *b = c;
}

char *my_revstr(char *str)
{
    int start = 0;
    int end = 0;

    while (str[end] != '\0')
        end++;
    end--;
    while (end > start) {
        swap_char(&str[start], &str[end]);
        start++;
        end--;
    }
    return (str);
}

