char *my_strncpy(char *restrict dst, const char *restrict src, int sz)
{
    char *ret = dst;

    while (sz) {
        *dst = *src;
        if (!*src)
            break;
        dst++;
        src++;
        sz--;
    }
    while (sz) {
        *dst = 0;
        dst++;
        sz--;
    }
    return ret;
}

