static int get_sign(char const **str)
{
    int minus_count = 0;

    while (**str) {
        switch (**str) {
        case '-':
            minus_count++;
            break;
        case '+':
            break;
        default:
            return minus_count % 2 ? -1 : 1;
        }
        (*str)++;
    }
    return 0;
}

static int parse_number_base(char const *str, const char *base)
{
    long number = 0;
    int sign = get_sign(&str);
    char tmp[2] = {0};
    int base_len = my_strlen(base);
    const char *base_index;

    if (sign == 0)
        return 0;
    while (*str) {
        tmp[0] = *(str++);
        base_index = my_strstr(base, tmp);
        if (!base_index)
            break;
        number *= base_len;
        number += base_index - base;
        if ((number > 2147483648L && sign < 0) ||
            (number > 2147483647L && sign > 0))
            return 0;
    }
    return sign * number;
}

int my_getnbr_base(char const *str, const char *base)
{
    int number;

    number = parse_number_base(str, base);
    return number;
}

int my_strncmp(char const *s1, char const *s2, int n)
{
    if (!n--)
        return 0;
    for (; *s1 && *s2 && n && *s1 == *s2;) {
        s1++;
        s2++;
        n--;
    }
    return *s1 - *s2;
}

