}

static long divide_or_n(long a, long b)
{
    return (b ? a / b : a);
}

int my_putnbr_base(int nbr, const char *base)
{
    long n_tmp = nbr;
    long long_nb = nbr;
    int n_digits = 0;
    int base_len = my_strlen(base);

    if (long_nb < 0) {
        my_putchar('-');
        long_nb *= -1;
    }
    while (n_tmp / base_len) {
        n_tmp /= base_len;
        n_digits++;
    }
    for (int i = n_digits; i >= 0; i--) {
        n_tmp = divide_or_n(long_nb, (powi(base_len, i)));
        my_putchar(base[n_tmp % base_len]);
    }
    return 0;
}

