static void print_data(const char *str, int remaining)
{
    for (int i = 0; i < remaining; i++)
        if (my_isprint(str[i]))
            my_putchar(str[i]);
        else
            my_putchar('.');
}

static void print_hexdump(const char *str, int remaining)
{
    int left_to_print = 40;
    int offset = 0;

    while (offset < remaining) {
        my_putnbr(str[offset], 2);
        if (offset % 2) {
            my_putchar(' ');
            left_to_print--;
        }
        left_to_print -= 2;
        offset++;
    }
    while (left_to_print > 0) {
        my_putchar(' ');
        left_to_print--;
    }
}

static void print_line(const char *str, int *offset, int *remaining)
{
    int max_len = *remaining < 0x10 ? *remaining : 0x10;

    my_putnbr(*offset, 8);
    my_putchar(':');
    my_putchar(' ');
    print_hexdump(str, max_len);
    print_data(str, max_len);
    my_putchar('\n');
    *offset += 0x10;
    *remaining -= 0x10;
}

int my_showmem(const char *str, int size)
{
    int offset = 0;
    int remaining = size;

    while (offset < size)
        print_line(str + offset, &offset, &remaining);
    return 0;
}

