char *my_revstr(char *str)
{
    int len = my_strlen(str);
    char tmp;
    char *start = str;
    char *end = str + len - 1;

    for (int i = 0; i < len / 2; i++) {
        tmp = *start;
        *start = *end;
        *end = tmp;
        start++;
        end--;
    }
    return str;
}

