int type_char(char *c)
{
    if (c > 64 && c < 91) {
        return 1;
    } else if (c > 96 && c < 123) {
        return 0;
    } else if (c > 47 && c < 58) {
        return 2;
    }
    return -1;
}

char *switch_case(char *c)
{
    int type = type_char(c);
    if (type == 0) {
        c = c - 32;
    } else if (type == 1) {
        c = c + 32;
    }
    return c;
}

char *my_strcapitalize(char *str)
