static
int str_contains(char const *str, char c)
{
    int i = 0;

    for (; *str != '\0'; i++)
        if (*str++ == c)
            return i;
    return -1;
}

static
void compute_n(int *np, char s, char const *base)
{
    int n = *np;
    char next = str_contains(base, s);
    int base_len = my_strlen(base);

    if (n < (INT_MIN / base_len)) {
        *np = 1;
        return;
    }
    n *= base_len;
    if (n < (INT_MIN + next)) {
        *np = 1;
        return;
    }
    n -= next;
    *np = n;
}

static
int compute_real_value(int n, int negated)
{
    if (n == 1)
        return 0;
    n = negated & 1 ? n : -n;
    return (!(negated & 1) && n < 0) ? 0 : n;
}

int my_getnbr_base(char *str, char const *base)
{
    int n = 0;
    int negated = 0;

    if (str == NULL || base == NULL)
        return 0;
    for (int started = 0; *str != '\0' && n != 1; str++) {
        if (str_contains(base, *str) != -1) {
            started |= 1;
            compute_n(&n, *str, base);
            continue;
        }
        if (*str == '-' && !started) {
            negated++;
            continue;
        }
        if (*str != '+')
            break;
    }
    return compute_real_value(n, negated);
}

