static
void my_show_memblock(char const *mem, int n)
{
    int leftover = 16 - n;
    int group = 16;

    my_putchar(':');
    my_putchar(' ');
    while (n--) {
        my_puthex(*mem++, 2);
        if (group-- & 1)
            my_putchar(' ');
    }
    while (leftover--) {
        my_putchar(' ');
        my_putchar(' ');
        if (group-- & 1)
            my_putchar(' ');
    }
}

static
void my_show_ascii(char const *mem, int n)
{
    for (; n--; mem++)
        my_putchar(IS_PRINT(*mem) ? *mem : '.');
}

int my_showmem(char const *str, int size)
{
    char *p = (char *)str;

    for (; size > 0; p += 16) {
        my_puthex(p - str, 8);
        my_show_memblock(p, MIN(16, size));
        my_show_ascii(p, MIN(16, size));
        my_putchar('\n');
        size -= 16;
    }
    return 0;
}

