        }
        i++;
    }
    return -1;
}

static int get_number_of_digits_of_number(char const *str, char const *base)
{
    int i = get_index_of_first_number(str);
    int number_of_digits = 0;

    while (get_digit_from_char(str[i], base) != -1) {
        i++;
        number_of_digits++;
    }
    return (number_of_digits);
}

static int get_significant_digit_number(char const *str, char const *base)
{
    int i = get_index_of_first_number(str);
    int number_of_digits = 0;

    while (str[i] == base[0]) {
        i++;
    }
    while (get_digit_from_char(str[i], base) != -1) {
        i++;
        number_of_digits++;
    }
    return (number_of_digits);
}

static long long read_number(char const *str, char const *base,
    int base_number)
{
    int i = get_index_of_first_number(str);
    int index_by_end = get_number_of_digits_of_number(str, base);
    int end_index = i + index_by_end;
    long long number_read = 0;
    int digit_read = 0;

    while (i < end_index) {
        digit_read = get_digit_from_char(str[i], base);
        number_read += (long long)digit_read * power(base_number,
            index_by_end - 1);
        i++;
        index_by_end = end_index - i;
    }
    return (number_read * get_sign_of_number(str));
}

static int get_max_digit(int base_number)
