    return i;
}

static int get_number(char const *str, char const *base, int base_number)
{
    const int max_positive_value = 2147483647;
    const int min_negative_value = -2147483648;
    long long number_read = read_number(str, base, base_number);

    if (number_read > max_positive_value || number_read < min_negative_value) {
        return (0);
    }
    return (number_read);
}

