void *my_strcpy(char *dest, char const *src)
{
    int i = 0;

    while (src[i] != '\0') {
        dest[i] = src[i];
        i = i + 1;
    }
    dest[i] = '\0';
}

char *my_strncpy(char *dest , char const *src , int n)
{
    int i = 0;
    int j = 0;
    char *str = src;

    while (*str != '\0'){
        str++;
        j++;
    }
    while (i != n){
        if (i > j){
            dest[i] = '\0';
            return dest;
        }
        dest[i] = src[i];
        i++;
    }
    return dest;
}

int my_str_len(char const *str)
{
    int i = 0;

    while (*str != '\0'){
        str++;
        i++;
    }
    return i;
}

char *my_revstr(char *str)
{
    int j = my_str_len(str);
    int i = 0;
    char val[j] ;

    while (i < j) {
        val[i] = str[i];
        str[i] = str[j - 1];
        str[j - 1] = val[i];
        j--;
        i++;
    }
    return str;
}

