void boucle(int nv1, int i, int nv2, int not_i)
{
    int diff = i - not_i;

    while (diff >= 1){
        nv1 = str[i];
        nv2 = str[not_i];
        str[i] = nv2;
        str[not_i] = nv1;
        i -= 1;
        not_i += 1;
        diff = i - not_i;
    }
}

char *my_revstr(char *str)
{
    int nv1;
    int i = 0;
    int nv2;
    int not_i = 0;
    int diff = i - not_i;

    while (str[i] != '\0'){
        i += 1;
    }
    i -= 1;
    while (diff >= 1){
        boucle(nv1, i, nv2, not_i, diff);
    }
    return (str);
}

