        str[y + 1] = str[y + 1] - 32;
}

char *my_strcapitalize(char *str)
{
    my_strlowcase(str);
    for (int y = 0; str[y] != '\0'; y++) {
        if (y == 0 && str[y] <= 122 && str[y] >= 97)
            str[y] = str[y] - 32;
        if (str[y] == 32 || str[y] == 45 || str[y] == 43) {
            space(str, y);
        }
    }
    return str;
}

