char *my_revstr(char *str)
{
    int len = 0;
    int temp;

    for (int i = 0 ; str[i] != '\0' ; i++) {
        len++;
    }
    for (int i = 0 ; i < len ; i++) {
        temp = str[i];
        str[i] = str[len - 1];
        str[len - 1] = temp;
        len--;
    }
    return str;
}

