        }
        i++;
    }
    return 1;
}

void write_non_printable_char(int hex1, int hex2)
{
    write(1, "\\", 1);
    write(1, &hex1, 1);
    write(1, &hex2, 1);
}

int my_showstr(char const *str)
{
    int hex1;
    int hex2;

    if (my_str_isprintable(str)) {
        write(1, str, my_strlen(str));
        return 0;
    }
    for (int i = 0; str[i] != '\0'; i++) {
        if (str[i] >= 32 && str[i] <= 126) {
            write(1, &str[i], 1);
            continue;
        }
        hex1 = (str[i] / 16) + 48;
        hex2 = str[i] % 16;
        if (hex2 <= 9)
            hex2 += 48;
        else
            hex2 += 87;
        write_non_printable_char(hex1, hex2);
    }
}

int my_str_islower(char const *str)
{
    int i = 0;

    while (str[i] != '\0') {
        if (!(str[i] >= 97 && str[i] <= 122)) {
            return 0;
        }
        i++;
    }
    return 1;
}

int my_str_isnum(char const *str)
{
    int i = 0;

    while (str[i] != '\0') {
        if (!(str[i] >= 48 && str[i] <= 57)) {
            return 0;
        }
        i++;
    }
    return 1;
}

char *my_strupcase(char *str)
{
    for (int i = 0; i < my_strlen(str) && str[i] != '\0'; i++) {
        if (str[i] >= 97 && str[i] <= 122) {
            str[i] = str[i] - 32;
        }
    }
    return str;
}

int my_strcmp(char const *s1, char const *s2)
{
    int a = 0;
    int b = 0;

    for (int i = 0; i < my_strlen(s1); i++) {
        if (s1[i] == '\0') {
            break;
        }
        a += s1[i];
    }
    for (int i = 0; i < my_strlen(s2); i++) {
        if (s2[i] == '\0') {
            break;
        }
        b += s2[i];
    }
    return a - b;
}

int my_str_isalpha(char const *str)
{
    int i = 0;

    while (str[i] != '\0') {
        if (!(str[i] >= 65 && str[i] <= 90) &&
            !(str[i] >= 97 && str[i] <= 122)) {
            return 0;
        }
        i++;
    }
    return 1;
}

#include <stdlib.h>

int my_strlen(char const *str)
{
    char *ptr = (char *)str;
    int len = 0;

    while (1) {
        if (*ptr == '\0') {
            return len;
        } else {
            ptr++;
            len++;
        }
    }
}

char *my_strcpy(char *dest, char const *src)
{
    int len_str = my_strlen(src);
    int i = 0;

    if (len_str == 0) {
        dest[0] = '\0';
        return &dest[0];
    }
    while (i < len_str || src[i] != '\0') {
        dest[i] = src[i];
        i++;
    }
    dest[i] = '\0';
    return &dest[0];
}

char *my_strlowcase2(char *str)
{
    for (int i = 0; i < my_strlen(str) && str[i] != '\0'; i++) {
        if (str[i] >= 65 && str[i] <= 90) {
            str[i] = str[i] + 32;
        }
    }
    return str;
}

char *my_strcapitalize(char *str)
{
    int i = 0;
    int first = 1;

    my_strlowcase2(str);
    while (str[i] != '\0') {
        if (first && (str[i] >= 97 && str[i] <= 122)) {
            first = 0;
            str[i] = str[i] - 32;
            i++;
            continue;
        }
        if (!(str[i] >= 97 && str[i] <= 122) &&
            !(str[i] >= 48 && str[i] <= 57)) {
            first = 1;
        } else {
            first = 0;
        }
        i++;
    }
    return &str[0];
}

int my_str_isupper(char const *str)
{
    int i = 0;

    while (str[i] != '\0') {
        if (!(str[i] >= 65 && str[i] <= 90)) {
            return 0;
        }
        i++;
    }
    return 1;
}

void my_swap(char *a, char *b)
{
    char val_a = *a;
    char val_b = *b;

    *b = val_a;
    *a = val_b;
}

char *my_revstr(char *str)
{
    int len_str = my_strlen(str);

    for (int i = 0; i < len_str / 2; i++) {
        my_swap(&str[i], &str[len_str - i - 1]);
    }
    return &str[0];
}

