char *my_revstr(char *str)
{
    int n = 0;
    int hold = 0;
    int add = 0;
    int i = 0;

    while (str[n] != '\0'){
        ++n;
    }
    add = n + 1;
    while (i < n / 2) {
        hold = str[i];
        str[i] = str [n - i - 1];
        str[n - i - 1] = hold;
        i = i + 1;
    }
    str[add] = '\0';
    return (str);
}

