long long int power(long long int base, int exponent)
{
    long long int stock_number = base;

    if (exponent == 0) {
        return 1;
    }
    while (exponent > 1) {
        base *= stock_number;
        exponent--;
    }
    return base;
}

int modulo(int nbr, int base_number, int exponent)
{
    int result = 0;

    if (nbr < 0) {
        result = (nbr / power(base_number, exponent)) % base_number;
        result = -result;
    } else {
        result = (nbr / power(base_number, exponent)) % base_number;
    }
    return result;
}

