void reverse_string(char *str, int size_of_string)
{
    int index_start = 0;
    int index_end = size_of_string;
    char stock_char;
    int middle_string = 0;

    middle_string = size_of_string / 2;
    while (index_start < size_of_string) {
        stock_char = str[index_start];
        str[index_start] = str[index_end];
        str[index_end] = stock_char;
        if (index_start == middle_string) {
            break;
        }
        index_start++;
        index_end--;
    }
}

char *my_revstr(char *str)
{
    int size_of_string = 0;

    size_of_string = str_len(str) - 1;
    reverse_string(str, size_of_string);
    return str;
}

