int sg_length(char const *str)
{
    int length_string = 0;

    while (*str != '\0') {
        str++;
        length_string++;
    }
    return length_string;
}

static char *do_a(char *str, int i)
{
    if (str[i] >= 97 && str[i] <= 122)
        str[i] = str[i] - 32;
    return str;
}

static char *do_b(char *str, int i)
{
    if (str[i + 1] >= 97 && str[i + 1] <= 122)
        str[i + 1] = str[i + 1] - 32;
    return str;
}

static char *do_c(char *str, int i)
{
    if (str[i] >= 65 && str[i] <= 90)
        str[i] = str[i] + 32;
    return str;
}

char *my_strcapitalize(char *str)
{
    int i;

    for (i = 0; i < sg_length(str); i++) {
        if (i == 0) {
            do_a(str, i);
            continue;
        }
        if (str[i] == 32) {
            do_b(str, i);
            continue;
        }
        if (str[i] < 65 && str[i] > 90)
            do_c(str, i);
    }
    return str;
}

