static
int test_min_ma_int(int out, int neg, int str)
{
    return (214748364 < out ||
        (out == 214748364 &&
        ((neg == -1 && 8 < str) ||
        (neg == 1 && 7 < str))));
}

int my_getnbr(char const *str)
{
    int out = 0;
    short neg = 1;

    for (int i = 0; str[i] != '\0'; i++) {
        if (*(str + i) == '+')
            continue;
        if (*(str + i) == '-') {
            neg *= (out == 0 ? -1 : 1);
            continue;
        }
        if (*(str + i) < 48 || 57 < *(str + i))
            break;
        if (test_min_ma_int(out, neg, *(str + i) - 48))
            return 0;
        out *= 10;
        out += *(str + i) - 48;
    }
    return out * neg;
}

