static
char convert(int nb)
{
    if (0 <= nb && nb <= 9)
        return nb +'0';
    if (10 <= nb && nb < 36)
        return nb -10 +'a';
    return '#';
}

int my_putnbr_base(int nbr, char const *base)
{
    char out[20];
    int nbase = my_getnbr(base);
    int i = 0;
    int neg = 0;

    if (nbr < 0) {
        neg = 1;
        nbr *= -1;
    }
    for (;nbr / nbase; i++) {
        out[i] = convert(nbr % nbase);
        nbr /= nbase;
    }
    out[i] = convert(nbr);
    if (neg)
        out[i +1] = '-';
    my_revstr(out);
    write(1, out, i +1);
    return 0;
}

static char *to_hexa(short nb, char *out)
{
    int i = nb & (1 << 4) -1;

    out[0] = '\\';
    out[2] = i < 10 ? i + '0' : i -10 + 'a';
    i = nb >> 4 & (1 << 4) -1;
    out[1] = i < 10 ? i + '0' : i -10 + 'a';
    return out;
}

