{
    int len = str_len(str) -1;
    int len_base = len;
    char *strbase = str;
    char char1;
    char char2;

    while (len != (len_base / 2)) {
        str = strbase + len_base - len;
        char1 = *str;
        str = strbase + len;
        char2 = *str;
        str = strbase + len;
        *str = char1;
        str = strbase + len_base - len;
        *str = char2;
        len--;
    }
    return strbase;
}

