static int is_alpha(char c)
{
    if (c > 96 && c < 123) {
        return 1;
    } else if (c > 64 && c < 91) {
        return 1;
    } else {
        return 0;
    }
}

static int is_num(char c)
{
    if (c > 47 && c < 58) {
        return 1;
    } else {
        return 0;
    }
}

static void char_capitalize(char *str, int i)
{
    if (str[i] > 96 && str[i] < 123) {
        str[i] = str[i] - 32;
    }
}

static void char_lower(char *str, int i)
{
    if (str[i] > 64 && str[i] < 91) {
        str[i] = str[i] + 32;
    }
}

void capitalize_condition(char *str, int *i, int j)
{
    if (j == 0 && is_alpha(str[*i])) {
        char_capitalize(str, *i);
    } else if (j != 0 && is_alpha(str[*i])) {
        char_lower(str, *i);
    }
}

int capitalize_condition2(char *str, int *i)
{
    int j = *i + 1;

    if (!is_alpha(str[j]) && !is_num(str[j]) && str[j] != '\0') {
        return 1;
    } else {
        return 0;
    }
}

static void my_get_word(char *str, int *i)
{
    for (int j = 0; is_alpha(str[*i]) || is_num(str[*i]); j++) {
        capitalize_condition(str, i, j);
