static int get_sign(char const *str, int *i)
{
    int sign = 1;

    while (str[*i] == '+' || str[*i] == '-') {
        if (str[*i] == '-') {
            sign = -sign;
        }
        (*i)++;
    }
    return sign;
}

static int get_index(char const *str, char const *base, int *i)
{
    int j = 0;

    while (base[j] != '\0' && str[*i] != base[j]) {
        j++;
    }
    return j;
}

int my_getnbr_base(char const *str, char const *base)
{
    int len = my_strlen(base);
    int sign;
    int result = 0;
    int i = 0;
    int j;

    if (len < 2) {
        return 0;
    }
    sign = get_sign(str, &i);
    while (str[i] != '\0') {
        j = get_index(str, base, &i);
        if (base[j] == '\0') {
            return 0;
        }
        result = result * len + j;
        i++;
    }
    return sign * result;
}

int my_strncmp(char const *s1, char const *s2, int n)
{
    int i = 0;

    while (i < n && s1[i] != '\0' && s2[i] != '\0' && s1[i] == s2[i]) {
        if (i == n - 1 || (s1[i + 1] == '\0' && s2[i + 1] == '\0')) {
            return 0;
        }
        i++;
    }
    return s1[n - 1] - s2[n - 1];
}

