    } else {
        my_putchar('.');
    }
}

static void print_hex_line(char const *str, int size, int i)
{
    int j;

    for (j = 0; j < 16; j++) {
        if (i + j < size) {
            print_hex(str[i + j]);
        } else {
            my_putchar(' ');
            my_putchar(' ');
        }
        if (j % 2 == 1) {
            my_putchar(' ');
        }
    }
}

static void print_ascii_line(char const *str, int size, int i)
{
    int j;

    for (j = 0; j < 16 && i + j < size; j++) {
        print_ascii(str[i + j]);
    }
}

