void conversion_low(char *str, int i)
{
    char alph_up[27] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    char alph_low[27] = "abcdefghijklmnopqrstuvwxyz";
    int a = 0;

    while (a < 26) {
