static void display_content(char c)
{
    if (c < 32) {
        write(1, ".", 1);
    }else {
        write(1, &c, 1);
    }
}

int display_spaces(int space, int i)
{
    while (i < 16) {
        space++;
        write(1, " ", 1);
        write(1, " ", 1);
        if (space == 2) {
            write(1, " ", 1);
            space = 0;
        }
        i++;
        space++;
    }
    return space;
}

int display_content_hexa2(char c, int space)
{
    char c2;
    char *hexa = "0123456789abcdef";

    space++;
    c2 = hexa[c / 16];
    write(1, &c2, 1);
    c = hexa[c % 16];
    write(1, &c, 1);
    if (space == 2) {
        write(1, " ", 1);
        space = 0;
    }
    return space;
}

int display_content_hexa(char const *str, int line, int space)
{
    int bon = 0;

    for (int i = 0; i < 16 && bon == 0; i++) {
        if (str[i + line * 16] == 0) {
            space = display_spaces(space, i);
            bon = 1;
        }else {
            space = display_content_hexa2(str[i + line * 16], space);
        }
    }
    return space;
}

void display_count_hexa(int count, int p)
{
    char reste;

    if (p == 8)
        return;
    reste = (count % 10) + 48;
    display_count_hexa(count / 10, p + 1);
    write(1, &reste, 1);
}

