{
    int count_hexa = 0;
    int space = 0;
    int line = 0;

    while (line < size) {
        display_count_hexa(count_hexa, 0);
        count_hexa += 10;
        write(1, ": ", 2);
        space = display_content_hexa(str, line, space);
        for (int i = 0; i < 16 && str[i + line * 16] != 0; i++)
            display_content(str[i + line * 16]);
        line = line + 16;
