}

int other_func(char *str, int i)
{
    int k = i;
    int low_alpha = (str[k] >= 'a' && str[k] <= 'z');
    int upp_alpha = (str[k] >= 'A' && str[k] <= 'Z');

    while (!low_alpha && !upp_alpha) {
        k++;
        low_alpha = (str[k] >= 'a' && str[k] <= 'z');
        upp_alpha = (str[k] >= 'A' && str[k] <= 'Z');
    }
    while ((str[k] >= 'a' && str[k] <= 'z') || (str[k] >= 'A' &&
                str[k] <= 'Z')) {
        upper_words(str, k);
        k++;
    }
    return k;
}

int for_word(int i, char *str, int upper, int other)
{
    int j = i;

    if (upper && other == 0)
        str[i] += 32;
    if (!upper && other == 0)
        str[i] -= 32;
    if (other)
        return other_func(str, i);
    while ((str[j] >= 'a' && str[j] <= 'z') || (str[j] >= 'A' &&
                str[j] <= 'Z')) {
        j++;
    }
    return j;
}

char *my_strcapitalize(char *str)
{
    int i = 0;
    int low_alpha = (str[i] >= 'a' && str[i] <= 'z');
    int upp_alpha = (str[i] >= 'A' && str[i] <= 'Z');

    for (; str[i] != '\0'; i++) {
        low_alpha = (str[i] >= 'a' && str[i] <= 'z');
        upp_alpha = (str[i] >= 'A' && str[i] <= 'Z');
        if (low_alpha) {
            i = for_word(i, str, 0, 0);
        }
        if (upp_alpha) {
            i = for_word(i, str, 1, 0);
        }
        if (!low_alpha && !upp_alpha && str[i] != ' ') {
            i = for_word(i, str, 0, 1);
        }
    }
    return str;
}

