void display_text(char *str, int ds)
{
    int i = 0;

    my_putchar(' ');
    while (i < 16) {
        if (i > ds) {
            my_putchar('.');
            i = i + 1;
            continue;
        }
        if (str[i] < 32 || str[i] == 127)
            my_putchar('.');
