void display_hex(char *str, int ds, char *pattern)
{
    int i = 0;

    while (i < 16) {
        if (i % 2 == 0)
            my_putchar(' ');
        if (i < ds) {
            my_putchar(pattern[((unsigned) (*(str + i)) / 16) % 16]);
            my_putchar(pattern[(unsigned) (*(str + i)) % 16]);
        } else {
            my_putchar(' ');
            my_putchar(' ');
        }
        i = i + 1;
    }
}

