int turn_into_caps(char *str, int i)
{
    if (str[i] >= 97 && str[i] <= 122) {
        str[i] = (str[i] - 32);
    }
}

int turn_into_low(char *str, int i)
{
    if (str[i] >= 65 && str[i] <= 90){
        str[i] = (str[i] + 32);
    }else {
        str[i] = str[i];
    }
}

int zero(char *str, int *i)
{
    if (*i == 0){
        turn_into_caps(str, *i);
        *i = *i + 1;
    }
}

int if_parts(char *str, int i)
{
    int a = i - 1;

    if ((str[a] > 0 && str[a] < 48) || (str[a] > 57 && str[a] < 65)){
        turn_into_caps(str, i);
    }else if ((str[a] > 122) || (str[a] > 90 && str[a] < 97)) {
        turn_into_caps(str, i);
    }else{
        turn_into_low(str, i);
    }
}

