char principal(char *str, char const *to_find, int i, int tf_length)
{
    int counter = 0;
    int stop = 0;

    while (str[i] != '\0') {
        for (; str[i] != to_find[0] && str[i] != '\0' ; i++);
        if (str[i] == '\0')
            return 1;
        stop = i;
        for (; str[i] == to_find[counter] && str[i] != '\0' ; i++)
            counter++;
        if (to_find[counter] == '\0')
            return (i - tf_length);
        if (str[i] == '\0')
            return 1;
        i = stop + 1;
        counter = 0;
    }
}

