static int exponent(int number, int exp)
{
    int result = number;

    for (; exp > 1; exp--) {
        result *= number;
    }
    return (result);
}

static int count_digits(int number, int len)
{
    int digits = 0;
    int temp_number = number;

    while (temp_number > 0) {
        temp_number /= len;
        digits++;
    }
    return (digits);
}

static void display(int number, char const *base, int len, int limit)
{
    int digits = 0;
    int result = 0;
    int exp = 0;

    if (number >= len) {
        digits = (count_digits(number, len) - 1);
        for (; digits >= 0; digits--) {
            exp = digits ? exponent(len, digits) : 1;
            result = ((number / exp) % len);
            my_putchar(base[result]);
        }
        if (limit == 1) {
            my_putchar('8');
        }
    } else {
        my_putchar(base[number]);
    }
}

