char *my_strncpy(char *dest, char const *src, int n)
{
    int i = 0;
    int length = 0;

    while (src[length] != '\0')
        length++;
    while (n > i) {
        dest[i] = src[i];
        i++;
    }
    if (n > length)
        dest[i] = '\0';
    return dest;
}

void loop_patch(char const *to_find, int i, int j)
{
    if (str[i + j] != to_find[j])
        break;
}

int my_strlen2(char const *str)
{
    int i = 0;

    while (str[i] != '\0')
        i++;
    return i;
}

char *my_strstr(char *str, char const *to_find)
{
    int str_len = my_strlen2(str);
    int to_find_len = my_strlen2(to_find);
    int i = 0;
    int j = 0;

    while (i <= str_len - to_find_len) {
        while (j < to_find_len) {
            loop_patch(to_find, i, j);
            j++;
        }
        if (j == to_find_len)
            return &str[i];
        i++;
    }
}

int my_strlen(char const *str)
{
    int i = 0;

    while (str[i] != '\0')
        i++;
    return i;
}

char *my_revstr(char *str)
{
    char temp_char;
    int first_char = 0;
    int last_char = my_strlen(str) - 1;

    while (first_char < last_char) {
        temp_char = str[first_char];
        str[first_char] = str[last_char];
        str[last_char] = temp_char;
        first_char += 1;
        last_char -= 1;
    }
    return str;
}

