char *my_strcapitalize(char *str)
{
    char lastChar;

    for (int i = 0; str[i] != '\0'; i++) {
        if (is_space(lastChar) && (str[i] >= 'a' && str[i] <= 'z')) {
            str[i] = str[i] - 32;
            lastChar = str[i];
            continue;
        }
        if (str[i] >= 'A' && str[i] <= 'Z') {
            str[i] = str[i] + 32;
        }
        lastChar = str[i];
    }
    return str;
}

