int haystack(char *str, char const *to_find, int *index_ptr, int index_needle)
{
    for (int i = 0; to_find[i] != '\0'; i += 1) {
        if (str[(*index_ptr) + i] != to_find[i]) {
            *index_ptr = *index_ptr + i;
            return 0;
        }
    }
    index_needle = *index_ptr;
    *index_ptr = my_strlen(str);
    return index_needle;
}

char *my_strstr(char *str, char const *to_find)
{
    int index = 0;
    int index_needle = 0;
    int len = my_strlen(str);

    if (to_find[0] == '\0') {
        return str;
    }
    while (index < len) {
        index_needle = haystack(str, to_find, &index, index_needle);
        index += 1;
    }
    if (index_needle == 0) {
        return NULL;
    }
    str = &(str[index_needle]);
    return str;
}

