{
    if (p == 1)
        if (str[i + 1] >= 'a' && str[i + 1] <= 'z')
            str[i + 1] = str[i + 1] - 32;
    if (p == 2)
        if (str[i + 1] >= 'A' && str[i + 1] <= 'Z')
            str[i + 1] = str[i + 1] + 32;
    return;
}

void check_capitalize(char *str , int i)
{
    char l1 = str[i];
    char l2 = str[i + 1];

    if (l1 == ' ' || l1 == '+' || l1 == '-')
        is_it_capitalize(str , i , 1);
    if ((l1 <= 'z' && l1 >= 'a') || (l1 <= 'Z' && l1 >= 'A'))
        is_it_capitalize(str , i , 2);
    if (l1 <= '9' && l1 >= '0')
        is_it_capitalize(str , i , 2);
    return;
}

