    int i = 0;

    my_strcpy(temp_str, str);
    while (i < my_strlen(temp_str) && my_strlen(to_find) >= 1) {
        str[a] = begin ? temp_str[i] : str[a];
        if (temp_str[i] == to_find[a] || begin)
            a++;
        check_begin(to_find, &begin, &a, &i);
