void hexa_case(int n)
{
    if (n > 9) {
        my_putchar('a' + n % 10);
    } else {
        my_put_nbr(n);
    }
}

int my_putnbr_base(int n, char const *base)
{
    int     quo;
    int operator = base_operator(base);
    int div = operator;

    if (n < 0) {
        n = - n;
        my_putchar('-');
    }
    while (n / operator > div - 1) {
        operator *= div;
    }
    while (operator > div - 1) {
        quo = n / operator;
        hexa_case(quo);
        n %= operator;
        operator /= div;
    }
    hexa_case(n);
    return 0;
}

