int my_put_nbr(int nb)
{
    int    quo;
    int operator = 1;

    if (nb < 0) {
        my_putchar('-');
        nb = -nb;
    }
    while (nb / operator > 9) {
        operator *= 10;
    }
    while (operator > 9) {
        quo = nb / operator;
        my_putchar(quo + '0');
        nb %= operator;
        operator /= 10;
    }
    my_putchar(nb + '0');
    return 0;
}

